  "supportive_card_ids": ["C03","C21","C25","C06","C12","C13","C23","C33","C05","C16","C26","C29","C30","C32","C35","C04"],
  "contradictory_card_ids": ["C27"],
  "prediction_basis_card_ids": ["C03","C21","C25","C33","C04"],
  "claims": [
    {
      "claim": "Bumetanide, the same sulfamoylbenzoic acid loop diuretic class as the query, has absolute oral bioavailability of 95% in patients with cirrhosis (L1) and 95 to 100% (L2), providing direct same-class same-condition evidence for F >= 20%.",
      "card_ids": ["C03","C21","C25"]
    },
    {
      "claim": "Multiple cirrhosis-context records show high oral bioavailability: metoclopramide 79 to 82% with 82% versus 60% in controls, and tolfenamic acid about 91 to 126%, supporting that cirrhosis in this evidence set is associated with high F.",
      "card_ids": ["C06","C12","C13","C23","C33","C05","C16","C26","C29","C30","C32","C35"]
    },
    {
      "claim": "The closest structural analog azosemide has L1 absolute F of approximately 20.4% in healthy fasted humans, above the threshold, although an L2 urinary-recovery estimate suggests about 10% in normal fasted subjects; this conflict is from a different condition and does not affirm F < 20% for the query.",
      "card_ids": ["C04","C27"]
    },
    {
      "claim": "The physicochemical prior (low logD, high TPSA, full ionization) suggests poor passive permeability, but it is not an affirmative endpoint measurement and is outweighed by the direct human bioavailability records.",
      "card_ids": ["C03","C21","C25","C33","C04"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C25","C26","C29","C30","C32","C33","C35"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C27"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C24","C28","C31","C34"]
    }
  ],
  "evidence_gaps": [
    "No direct furosemide-specific oral bioavailability record is present in the supplied cards; the decision relies on same-class (bumetanide) and structural-analog (azosemide) transfer.",
    "Azosemide records conflict (20.4% L1 versus 10% L2) and come from healthy fasted subjects, not cirrhosis, leaving uncertainty about the analog magnitude.",
    "Cirrhosis severity, formulation, and dose effects on furosemide absorption are not specified in the evidence.",
    "The physicochemical prior indicates poor passive permeability, but no direct absorption or first-pass measurement for the query is supplied."
  ],
  "decision_summary": "Predicted high (F >= 20%) because the same-class same-condition evidence (bumetanide in cirrhosis, F=95% L1 and 95 to 100% L2) and multiple cirrhosis-context records (metoclopramide 79 to 82%, tolfenamic acid about 91 to 126%) support high F; the closest analog azosemide has L1 F=20.4% above threshold though an L2 estimate is about 10% in healthy fasted subjects; no affirmative evidence supports F < 20% in cirrhosis. Confidence is moderate due to reliance on transfer and the conflicting analog estimates."
}

